{{--
    N'importe quel bouton ouvre le sélecteur de fichiers.

    <x-ui.file-trigger wire:model="invoice" accept=".pdf" max-size="10MB">
        <x-ui.button variant="outline">Upload file</x-ui.button>
    </x-ui.file-trigger>

    Deux inputs cachés : celui qu'ouvre le bouton, et celui que lisent
    Livewire ou le formulaire (`wire:model`, `name`). Seuls les fichiers
    acceptés passent du premier au second : un fichier refusé n'est jamais
    envoyé. Le serveur valide quand même : `accept` et `max-size` ne font
    qu'aider. Moteur : Alpine.data('fwFiles'), resources/js/plugins/files.js.
--}}
@props([
    'name' => null,
    'accept' => null,
    'multiple' => false,
    'directory' => false,
    'capture' => null,
    'maxSize' => null,
    'maxFiles' => null,
    'showFiles' => true,
    'disabled' => false,
    'removeLabel' => 'Remove :name',
    'texts' => [],
])

@php
    $model = $attributes->wire('model')->value();
    $id = $attributes->get('id') ?? 'file-trigger-'.\Illuminate\Support\Str::slug($name ?? $model ?? 'file').'-'.substr(md5((string) json_encode([$name, $model, $accept])), 0, 6);
    $config = \App\Flexiwind\FileRules::config($accept, $maxSize, $maxFiles, (bool) $multiple, $model, $removeLabel, $texts);
@endphp

<div data-slot="file-trigger" id="{{ $id }}" x-data="fwFiles(@js($config))"
    {{ $attributes->whereDoesntStartWith('wire:model')->except(['id'])->class(['flex flex-col gap-2']) }}>
    <div class="contents" x-on:click="openFrom($event)">{{ $slot }}</div>

    <input type="file" x-ref="picker" hidden tabindex="-1" aria-hidden="true" x-on:change="pick($event.target.files)"
        @if ($accept) accept="{{ $accept }}" @endif
        @if ($multiple) multiple @endif
        @if ($directory) webkitdirectory @endif
        @if ($capture) capture="{{ $capture }}" @endif
        @if ($disabled) disabled @endif>
    <input type="file" x-ref="model" hidden tabindex="-1" aria-hidden="true"
        @if ($name) name="{{ $name }}{{ $multiple && ! str_ends_with($name, '[]') ? '[]' : '' }}" @endif
        @if ($multiple) multiple @endif
        {{ $attributes->whereStartsWith('wire:model') }}>

    @if ($showFiles)
        <x-ui.file-trigger.files />
    @endif
</div>

{{--
    Une zone où déposer des fichiers ; un clic, Entrée ou Espace ouvre aussi
    le sélecteur. Mêmes règles que <x-ui.file-trigger> : seuls les fichiers
    acceptés partent, et le serveur valide à nouveau.

    <x-ui.dropzone wire:model="attachments" multiple accept="image/png,image/jpeg,.pdf" max-size="10MB" />
--}}
@props([
    'name' => null,
    'label' => null,
    'accept' => null,
    'multiple' => false,
    'maxSize' => null,
    'maxFiles' => null,
    'hint' => null,
    'title' => 'Drop files here or :browse',
    'browseText' => 'browse',
    'overText' => 'Release to add the files',
    'showFiles' => true,
    'size' => 'md',
    'disabled' => false,
    'invalid' => false,
    'removeLabel' => 'Remove :name',
    'texts' => [],
])

@php
    $model = $attributes->wire('model')->value();
    $id = $attributes->get('id') ?? 'dropzone-'.\Illuminate\Support\Str::slug($name ?? $model ?? 'files').'-'.substr(md5((string) json_encode([$name, $model, $accept, $label])), 0, 6);
    $config = \App\Flexiwind\FileRules::config($accept, $maxSize, $maxFiles, (bool) $multiple, $model, $removeLabel, $texts);
    $errorKey = $model ?: ($name ? str_replace(['[]', '[', ']'], ['', '.', ''], $name) : null);
    $error = $errorKey && isset($errors) ? ($errors->first($errorKey) ?: $errors->first($errorKey.'.*')) : '';
    $isInvalid = $invalid || $error !== '';
    [$before, $after] = array_pad(explode(':browse', e($title), 2), 2, '');
@endphp

<div data-slot="dropzone" id="{{ $id }}" x-data="fwFiles(@js($config))" @if ($isInvalid) data-invalid @endif
    {{ $attributes->whereDoesntStartWith('wire:model')->except(['id'])->class(['group/dropzone flex w-full min-w-0 flex-col gap-2']) }}>
    @if ($label)
        <span id="{{ $id }}-label" class="text-sm font-medium text-title-foreground">{{ $label }}</span>
    @endif

    <div role="button" @if ($disabled) aria-disabled="true" tabindex="-1" @else tabindex="0" @endif
        @if ($label) aria-labelledby="{{ $id }}-label {{ $id }}-title" @endif
        aria-describedby="{{ $id }}-hint"
        x-on:click="browse()" x-on:keydown.enter.prevent="browse()" x-on:keydown.space.prevent="browse()"
        x-on:dragenter.prevent="dragEnter($event)" x-on:dragover.prevent x-on:dragleave="dragLeave()" x-on:drop.prevent="drop($event)"
        x-bind:data-over="over ? '' : null"
        @class([
            'group/zone flex w-full flex-col items-center justify-center gap-2.5 rounded-ui border-[1.5px] border-dashed border-border-strong bg-background text-center',
            'transition-colors duration-150 outline-2 outline-offset-2 outline-transparent focus-visible:outline-(--ui-input-focus-outline)',
            'data-over:border-primary data-over:bg-primary/8',
            'group-data-invalid/dropzone:border-(--ui-input-invalid-outline)',
            'px-5 py-7' => $size !== 'sm',
            'flex-row px-4 py-3.5' => $size === 'sm',
            'cursor-not-allowed opacity-60' => $disabled,
            'cursor-pointer enabled:hover:border-muted-foreground/50' => ! $disabled,
        ])>
        @if ($size !== 'sm')
            <span aria-hidden="true" class="flex size-10 items-center justify-center rounded-ui border border-border bg-background text-title-foreground shadow-xs group-data-over/zone:border-primary/35 group-data-over/zone:text-primary">
                <span class="flex size-4.5 iconify ph--cloud-arrow-up group-data-over/zone:hidden"></span>
                <span class="hidden size-4.5 iconify ph--upload-simple group-data-over/zone:flex"></span>
            </span>
        @endif
        <span id="{{ $id }}-title" class="text-sm font-medium text-title-foreground group-data-over/zone:hidden">{!! $before !!}<span class="text-primary underline decoration-primary/40 underline-offset-3">{{ $browseText }}</span>{!! $after !!}</span>
        <span class="hidden text-sm font-medium text-primary group-data-over/zone:inline">{{ $overText }}</span>
        @if ($hint && $size !== 'sm')
            <span id="{{ $id }}-hint" class="text-xs text-muted-foreground">{{ $hint }}</span>
        @else
            <span id="{{ $id }}-hint" class="sr-only">{{ $hint }}</span>
        @endif
    </div>

    <input type="file" x-ref="picker" hidden tabindex="-1" aria-hidden="true" x-on:change="pick($event.target.files)"
        @if ($accept) accept="{{ $accept }}" @endif
        @if ($multiple) multiple @endif
        @if ($disabled) disabled @endif>
    <input type="file" x-ref="model" hidden tabindex="-1" aria-hidden="true"
        @if ($name) name="{{ $name }}{{ $multiple && ! str_ends_with($name, '[]') ? '[]' : '' }}" @endif
        @if ($multiple) multiple @endif
        {{ $attributes->whereStartsWith('wire:model') }}>

    @if ($showFiles)
        <x-ui.file-trigger.files />
    @endif

    @if ($error !== '')
        <p class="flex items-center gap-1.5 text-xs text-destructive" role="alert">
            <span aria-hidden="true" class="flex size-3.5 shrink-0 iconify ph--warning-circle"></span>{{ $error }}
        </p>
    @endif
</div>

/**
 * Fichiers Flexiwind : <x-ui.file-trigger> et <x-ui.dropzone>.
 *
 * Deux inputs : `picker`, ouvert par le bouton ou la zone, et `model`, que
 * lisent Livewire (wire:model) ou le formulaire (`name`). Un choix est
 * vérifié ici (type, taille, nombre) puis seuls les fichiers acceptés sont
 * copiés dans `model` : Livewire n'envoie jamais un fichier refusé.
 *
 * Ces vérifications aident ; le serveur valide à nouveau (`mimes`, `max`),
 * car ce qu'envoie un navigateur peut être forgé.
 */

export function FilesPlugin(Alpine) {
    Alpine.data("fwFiles", files);
}

let sequence = 0;

function fill(text, values) {
    return Object.entries(values).reduce((result, [key, value]) => result.replaceAll(`:${key}`, value), text ?? "");
}

export function humanSize(bytes) {
    const units = [["GB", 1024 ** 3], ["MB", 1024 ** 2], ["KB", 1024]];

    for (const [unit, size] of units) {
        if (bytes >= size) {
            const value = bytes / size;

            return `${Number(value.toFixed(value < 10 ? 1 : 0))} ${unit}`;
        }
    }

    return `${bytes} B`;
}

/** Le fichier correspond-il à `accept` (`.pdf`, `image/*`, `application/pdf`) ? */
export function accepts(file, accept) {
    if (!accept?.length) {
        return true;
    }

    const name = file.name.toLowerCase();
    const type = (file.type || "").toLowerCase();

    return accept.some((rule) => {
        if (rule.startsWith(".")) {
            return name.endsWith(rule);
        }

        if (rule.endsWith("/*")) {
            return type.startsWith(rule.slice(0, -1));
        }

        return type === rule;
    });
}

function files(config = {}) {
    const texts = config.texts ?? {};
    const previews = new Set();

    return {
        files: [],
        over: false,
        depth: 0,

        init() {
            // Le serveur vide la propriété (après un enregistrement) : la liste suit.
            if (this.livewire() && typeof this.$wire.$watch === "function") {
                this.$wire.$watch(config.model, (value) => {
                    const empty = value === null || value === undefined || (Array.isArray(value) && value.length === 0);
                    const settled = this.files.every((row) => row.rejected || row.status === "done" || row.status === "error");

                    if (empty && settled) {
                        this.clearPreviews();
                        this.files = [];
                    }
                });
            }
        },

        destroy() {
            previews.forEach((url) => URL.revokeObjectURL(url));
        },

        // ------------------------------------------------------------ ouverture

        browse() {
            if (this.$refs.picker.disabled) {
                return;
            }

            this.$refs.picker.value = "";
            this.$refs.picker.click();
        },

        /** Un clic sur le bouton du slot ouvre le sélecteur. */
        openFrom(event) {
            const trigger = event.target.closest("button, a, [role=button]");

            if (trigger && !trigger.disabled) {
                event.preventDefault();
                this.browse();
            }
        },

        dragEnter(event) {
            if (this.$refs.picker.disabled || !event.dataTransfer?.types?.includes("Files")) {
                return;
            }

            this.depth += 1;
            this.over = true;
        },

        dragLeave() {
            this.depth = Math.max(0, this.depth - 1);
            this.over = this.depth > 0;
        },

        drop(event) {
            this.depth = 0;
            this.over = false;

            if (!this.$refs.picker.disabled) {
                this.pick(event.dataTransfer?.files ?? []);
            }
        },

        // ------------------------------------------------------------ choix

        pick(list) {
            let picked = [...list];

            if (!config.multiple) {
                picked = picked.slice(0, 1);
            }

            this.clearPreviews();

            let accepted = 0;
            const rows = picked.map((file) => {
                let reason = null;

                if (!accepts(file, config.accept)) {
                    reason = texts.type;
                } else if (config.maxBytes && file.size > config.maxBytes) {
                    reason = fill(texts.size, { max: config.maxLabel });
                } else if (config.maxFiles && accepted >= config.maxFiles) {
                    reason = fill(texts.count, { max: config.maxFiles });
                } else {
                    accepted += 1;
                }

                return this.row(file, reason);
            });

            // Un nouveau choix remplace le précédent, comme un input natif.
            this.files = rows;
            this.commit();
        },

        row(file, reason) {
            let preview = null;

            if (!reason && file.type.startsWith("image/") && file.size < 15 * 1024 * 1024) {
                preview = URL.createObjectURL(file);
                previews.add(preview);
            }

            return {
                id: ++sequence,
                file,
                name: file.name,
                size: file.size,
                preview,
                rejected: !!reason,
                reason,
                status: reason ? "rejected" : this.livewire() ? "uploading" : "ready",
                progress: 0,
            };
        },

        /** Copie les fichiers acceptés dans l'input lu par Livewire ou le formulaire. */
        commit() {
            const transfer = new DataTransfer();
            this.files.filter((row) => !row.rejected).forEach((row) => transfer.items.add(row.file));

            const model = this.$refs.model;
            model.files = transfer.files;

            if (!this.livewire()) {
                return;
            }

            if (!transfer.files.length) {
                this.$wire?.$set(config.model, config.multiple ? [] : null);

                return;
            }

            this.listen(model);
            model.dispatchEvent(new Event("change", { bubbles: true }));
        },

        livewire() {
            return !!config.model && !!this.$wire;
        },

        /** Les événements d'envoi de Livewire, posés une fois sur l'input. */
        listen(model) {
            if (model._fwListening) {
                return;
            }

            model._fwListening = true;
            const uploading = () => this.files.filter((row) => !row.rejected && row.status !== "done");

            model.addEventListener("livewire-upload-start", () => uploading().forEach((row) => { row.status = "uploading"; row.progress = 0; }));
            model.addEventListener("livewire-upload-progress", (event) => uploading().forEach((row) => { row.progress = event.detail?.progress ?? row.progress; }));
            model.addEventListener("livewire-upload-finish", () => uploading().forEach((row) => { row.status = "done"; row.progress = 100; }));
            model.addEventListener("livewire-upload-error", () => uploading().forEach((row) => { row.status = "error"; }));
            model.addEventListener("livewire-upload-cancel", () => uploading().forEach((row) => { row.status = "error"; }));
        },

        // ------------------------------------------------------------ retrait

        remove(target) {
            const kept = this.files.filter((row) => row !== target && !row.rejected);
            const index = this.files.filter((row) => !row.rejected).indexOf(target);

            if (target.preview) {
                URL.revokeObjectURL(target.preview);
                previews.delete(target.preview);
            }

            this.files = this.files.filter((row) => row !== target);

            if (target.rejected) {
                return;
            }

            const transfer = new DataTransfer();
            kept.forEach((row) => transfer.items.add(row.file));
            this.$refs.model.files = transfer.files;

            if (this.livewire()) {
                this.removeUpload(index);
            }
        },

        /** Retire le fichier déjà envoyé à Livewire, sans renvoyer les autres. */
        removeUpload(index) {
            const current = this.$wire.get(config.model);
            const values = Array.isArray(current) ? current : current ? [current] : [];
            // « livewire-file:<signature>:<nom> » : le nom temporaire est la dernière partie.
            const name = typeof values[index] === "string" && values[index].startsWith("livewire-file:") ? values[index].split(":").pop() : null;

            if (name && config.multiple) {
                this.$wire.removeUpload(config.model, name);
            } else {
                this.$wire.$set(config.model, config.multiple ? [] : null);
            }
        },

        clearPreviews() {
            previews.forEach((url) => URL.revokeObjectURL(url));
            previews.clear();
        },

        // ------------------------------------------------------------ textes

        meta(row) {
            const size = humanSize(row.size);

            if (row.rejected) {
                return `${size} · ${row.reason}`;
            }

            return fill(texts[row.status] ?? texts.ready, { size, progress: Math.round(row.progress) });
        },

        removeLabel(row) {
            return fill(texts.remove, { name: row.name });
        },
    };
}
